/* @lc app=leetcode id=3500 lang=kotlin */
class Solution { fun minimumCost(nums: IntArray, cost: IntArray, k: Int): Long = LongArray(nums.size).also { p -> nums.foldIndexed(0L) { i, acc, v -> (acc + v).also { p[i] = it } } }.let { pref -> LongArray(nums.size + 1).also { s -> (nums.size - 1 downTo 0).forEach { i -> s[i] = s[i + 1] + cost[i] } }.let { suff -> LongArray(nums.size + 1).also { dp -> (nums.size - 1 downTo 0).forEach { i -> dp[i] = (i until nums.size).minOf { j -> (pref[j] - (if (i == 0) 0L else pref[i - 1]) + k) * suff[i] + dp[j + 1] } } }[0] } } }